sys_script.script:
(function () {
    var entregaSysId = current.getValue('entrega');
    var novoStatus = current.getValue('novo_status');

    if (!entregaSysId) {
        gs.error('Update Entrega from Tracking: entrega reference is empty on tracking record ' + current.getUniqueValue());
        return;
    }

    if (!novoStatus) {
        return;
    }

    var gr = new GlideRecord('x_915815_smart_log_entrega');
    if (gr.get(entregaSysId)) {
        gr.setValue('status', novoStatus);

        var dataAtualizacao = current.getValue('data_atualizacao');
        if (dataAtualizacao) {
            gr.setValue('ultima_atualizacao', dataAtualizacao);
        } else {
            var now = new GlideDateTime();
            gr.setValue('ultima_atualizacao', now.getValue());
        }

        gr.update();
    } else {
        gs.error('Update Entrega from Tracking: could not find entrega with sys_id ' + entregaSysId);
    }
})();
